@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class CommandLine_ESTest_test32 extends CommandLine_ESTest_scaffolding {

    /**
     * When an option was never parsed and the default-value supplier is null,
     * getParsedOptionValue(char, Supplier) returns null.
     */
    @Test(timeout = 4000)
    public void getParsedOptionValueForMissingOptionWithNullSupplierReturnsNull() throws Throwable {
        CommandLine commandLine = new CommandLine();
        Supplier<Class<Option>> nullDefaultValueSupplier = null;

        Class<Option> parsedValue = commandLine.getParsedOptionValue('a', nullDefaultValueSupplier);

        assertNull(parsedValue);
    }
}
